// Actifs de l'identité visuelle ANIKA (documents PDF) : polices Italiana et
// Jura (licence SIL OFL — voir actifs-anika/), cachet. Encodés en base64 pour
// être embarqués dans le fichier unique de l'application.

const depuisB64 = (b64) => Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));

const ITALIANA_B64 = '';
const JURA_LIGHT_B64 = '';
const JURA_MEDIUM_B64 = '';
const CACHET_B64 = '';

export const octetsItaliana = () => depuisB64(ITALIANA_B64);
export const octetsJuraLight = () => depuisB64(JURA_LIGHT_B64);
export const octetsJuraMedium = () => depuisB64(JURA_MEDIUM_B64);
export const octetsCachet = () => depuisB64(CACHET_B64);
